void wpa_dbg(void *ctx, int level, const char *fmt, ...)
{
	va_list ap;
	char *buf;
	int buflen;

	if (level >= wpa_debug_level) {
		va_start(ap, fmt);
		buflen = vsnprintf(NULL, 0, fmt, ap) + 1;
		va_end(ap);

		buf = os_malloc(buflen);
		if (buf == NULL) {
			WPA_LOGW("wpa_msg: Failed to allocate message "
				   "buffer");
			return;
		}
		va_start(ap, fmt);

		vsnprintf(buf, buflen, fmt, ap);
		va_end(ap);
		WPA_LOGD("%s\n", buf);
		os_free(buf);
	}
}


