/* vote bookkeeping (pm.c:2218)                                        */
/* ------------------------------------------------------------------ */

static uint8_t s_hp_pm_cpu_freq[PM_DEV_ID_MAX];
static pm_cpu_freq_e s_hp_current_cpu_freq = PM_CPU_FRQ_26M;

