int os_get_random(unsigned char *buf, size_t sz)
{
	int r;
	int len;

	while (sz > 0) {
		len = sizeof(r) > sz ? sz : sizeof(r);
		r = rand();
		os_memcpy(buf, &r, len);
		buf += len;
		sz -= len;
