#include <driver/_otp.h>

#define TAG "init"

/* components_init.c:97, verbatim apart from the hp_ prefix. */

int hp_bandgap_init(void)
{
#if (CONFIG_SOC_BK7236XX) && (CONFIG_OTP_V1)
	uint8_t device_id[2]; //only check seqNUM
