              return;
            }

          /* buf/len describe the whole 802.3 frame, header included, exactly
           * as the vendor bridge passes it. */

          params.buf  = (unsigned char *)p->payload;
          params.len  = p->len;
          params.flag = iface;
          params.freq = 0;

