          pbuf_free(p);
          return;
        }
    }
#endif /* CONFIG_BK7258_WIFI_VENDOR_RUNTIME */

  vpkt = bk7258_vpkt_alloc(p->tot_len, true);
  if (vpkt == NULL)
    {
      pbuf_free(p);
      return;
    }

  dst = vpkt->payload;
  for (q = p; q != NULL; q = q->next)
    {
      memcpy(dst, q->payload, q->len);
      dst += q->len;
    }
  bk7258_wifi_lower_rx_submit(&g_bk7258_wifi, vpkt);
  pbuf_free(p);
}

